H.background();
const rho = P.rho, L = P.len, A = P.area;
const R = rho * L / Math.max(A, 1e-6);
H.text("Resistance:  R = rho · L / A", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
const midY = H.H * 0.52, x0 = 60;
const maxLen = H.W - 200;
const wireLen = H.clamp(40 + (L / 5) * maxLen, 40, maxLen);
const thick = H.clamp(8 + A * 40, 8, 70);
const hue = H.clamp(210 - rho * 60, 0, 210);
const bandColor = H.hsl(hue, 70, 55);
H.rect(x0, midY - thick / 2, wireLen, thick, { fill: bandColor, stroke: H.colors.grid, width: 2, radius: 6 });
H.text("L (length)", x0 + wireLen / 2 - 28, midY - thick / 2 - 10, { color: H.colors.accent, size: 12 });
H.line(x0, midY + thick / 2 + 8, x0 + wireLen, midY + thick / 2 + 8, { color: H.colors.accent, width: 1.5 });
H.line(x0 + wireLen + 14, midY - thick / 2, x0 + wireLen + 14, midY + thick / 2, { color: H.colors.good, width: 1.5 });
H.text("A", x0 + wireLen + 20, midY + 4, { color: H.colors.good, size: 12 });
const speed = H.clamp(120 / Math.max(R, 0.2), 10, 200);
const N = 7;
for (let i = 0; i < N; i++) {
  let xp = ((t * speed / wireLen + i / N) % 1);
  const ex = x0 + xp * wireLen;
  const ey = midY + (Math.sin((i + xp * 4) * 2) * thick * 0.25);
  H.circle(ex, ey, 4, { fill: H.colors.warn, stroke: H.colors.bg, width: 1 });
}
H.text("rho = " + rho.toFixed(2) + " Ω·m    L = " + L.toFixed(2) + " m    A = " + A.toFixed(3) + " m²", 24, 54, { color: H.colors.sub, size: 13 });
H.text("R = rho·L/A = " + R.toFixed(2) + " Ω", 24, H.H - 24, { color: H.colors.good, size: 15, weight: 700 });
H.text("longer wire -> more R · thicker wire -> less R · better conductor (small rho) -> less R", 24, H.H - 6, { color: H.colors.sub, size: 11 });
